def translate(s):
    return "".join(code.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def find_orfs(s, minaa=30):
    res=[]
    for strand,s2 in (('+',s),('-',rc(s))):
        for f in range(3):
            t = translate(s2[f:])
            i=0
            for prot in t.split('*'):
                L=len(prot)
