                            start = f + i*3 + st*3
                        else:
                            start = len(s) - (f + i*3 + L*3)
                        res.append((strand,start,L,prot[:60]))
                i+=L+1
    return res

for r in sorted(find_orfs(seq,50), key=lambda x:-x[2])[:20]:
    print(r)
