seq = "".join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
N=len(seq)
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
code = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for a in bases:
    for b in bases:
        for c in bases:
            code[a+b+c]=aas[i]; i+=1
def tr(s): return "".join(code.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

STOPS=('TAA','TAG','TGA')

# Six frame stop/start map, using plus-strand coordinates 1-based, inclusive.
def frames():
    for strand in ('+','-'):
        s = seq if strand=='+' else rc(seq)
        for f in range(3):
            yield strand,f,s[f:]

for strand,f,s in frames():
    # position of codon k (0-based) in this reading frame:
    # plus: plus_start = f + 3k + 1 ; minus: the codon occupies plus coords (N-f-3k) down to (N-f-3k-2)
    stops=[]; atgs=[]
    for k in range(len(s)//3):
        cod=s[3*k:3*k+3]
        if strand=='+':
            p=f+3*k+1
        else:
            p=N-(f+3*k)-2   # leftmost plus coord of the codon triple
        if cod in STOPS: stops.append(p)
        if cod in ('ATG','GTG','TTG'): atgs.append((p,cod))
    print(strand,f,"stops:",stops)
