for a in bases:
    for b in bases:
        for c in bases:
            code[a+b+c]=aas[i]; i+=1
STOPS={'TAA','TAG','TGA'}

mseq=rc(seq)

def orfs_minus(minaa):
    res=[]
    for f in range(3):
        k=0
        ncod=(N-f)//3
        while k<ncod:
            if mseq[f+3*k:f+3*k+3]=='ATG':
                k2=k
                while k2<ncod and mseq[f+3*k2:f+3*k2+3] not in STOPS:
                    k2+=1
                L=k2-k
                if L>=minaa:
                    left = N-f-3*k2-2   # leftmost coord of stop codon
                    right= N-f-3*k          # start codon, high coord
                    res.append((f,left,right,L))
                k=k2+1
            else:
                k+=1
    return res

print("MINUS-strand ORFs >=80 aa  (frame, coding region plus coords [left..right], codons)")
